/bin/bash -lc 'extract_headers() {
  local file="$1"
  awk -v file="$file" '"'
    function normalize(s) { gsub(/[[:space:]]+/, \"\", s); return s }
    function start_decl(line, t, n, a) {
      t = line
      while (t ~ /"'^(private|protected|noncomputable|unsafe)[[:space:]]+/) {
        sub(/''^(private|protected|noncomputable|unsafe)[[:space:]]+/, "", t)
      }
      if (t !~ /''^(theorem|lemma|def|abbrev|structure|class|inductive)[[:space:]]+/) return ""
      split(t, a, /[[:space:]]+/)
      n = a[2]
      sub(/[({:].*$/, "", n)
      return n
    }
    function finish_header(kind, line) {
      if (kind == "theorem" || kind == "lemma") return line ~ /:=[[:space:]]*by([[:space:]]|$)/
      if (kind == "structure" || kind == "class" || kind == "inductive") return line ~ /[[:space:]]where([[:space:]]|$)/
      return line ~ /:=/
    }
    function decl_kind(line, t, a) {
      t = line
      while (t ~ /''^(private|protected|noncomputable|unsafe)[[:space:]]+/) {
        sub(/''^(private|protected|noncomputable|unsafe)[[:space:]]+/, "", t)
      }
      split(t, a, /[[:space:]]+/)
      return a[1]
    }
    {
      if (!active) {
        name = start_decl($0)
        if (name != "") {
          active = 1
          kind = decl_kind($0)
          header = $0
          if (finish_header(kind, $0)) {
            sub(/:=[[:space:]]*by.*/, "", header)
            sub(/[[:space:]]where([[:space:]].*)?$/, "", header)
            if (kind != "theorem" && kind != "lemma") sub(/:=.*/, "", header)
            print file "'"\\t\" name \"\\t\" normalize(header)
            active = 0
          }
        }
      } else {
        header = header \" \" "'$0
        if (finish_header(kind, $0)) {
          sub(/:=[[:space:]]*by.*/, "", header)
          sub(/[[:space:]]where([[:space:]].*)?$/, "", header)
          if (kind != "theorem" && kind != "lemma") sub(/:=.*/, "", header)
          print file "'"\\t\" name \"\\t\" normalize(header)
          active = 0
        }
      }
    }
  '
}
export -f extract_headers
: > /tmp/issue729-base-headers.tsv
: > /tmp/issue729-current-headers.tsv
while IFS= read -r file; do
  git show HEAD:\""'$file" | extract_headers "$file" >> /tmp/issue729-base-headers.tsv
  extract_headers "$file" < "$file" >> /tmp/issue729-current-headers.tsv
done < <(git diff --name-only -- MIPStarRE)
sort -u /tmp/issue729-base-headers.tsv -o /tmp/issue729-base-headers.tsv
sort -u /tmp/issue729-current-headers.tsv -o /tmp/issue729-current-headers.tsv
awk -F '"'\\t' 'NR==FNR {current["'$1 FS $2]=$3; next} {key=$1 FS $2; if (!(key in current)) print "MISSING'"\\t\" "'$0; else if (current[key] != $3) print "CHANGED'"\\t\" "'$0 "'"\\tCURRENT=\" current[key]}' \\
  /tmp/issue729-current-headers.tsv /tmp/issue729-base-headers.tsv > /tmp/issue729-header-drift.tsv
printf 'base headers scanned: '; wc -l < /tmp/issue729-base-headers.tsv
printf 'current headers scanned: '; wc -l < /tmp/issue729-current-headers.tsv
printf 'changed or missing base headers: '; wc -l < /tmp/issue729-header-drift.tsv
sed -n '1,120p' /tmp/issue729-header-drift.tsv"

